INSERT INTO zt_action (objectType,objectID,product,project,execution,actor,action,date,comment,files,extra,`read`,efforted,vision) VALUES ('bug',6418,'79','141','142','tiany','resolved',NOW(),'<p><b>根因</b>：历史记录「待提交 / 已提交归档」tab 错乱（待提交也被归入已提交、计数虚高，对应重开现象）。前端 src/stores/flood.ts 的 inspectionRowToRecord 把检查单状态写死为 submitted，未按后端每行返回的 bizState 区分；fetchHistoryRemote / countHistory 在远程模式下从未透传 status 过滤参数，两个 tab 都拉回全量且全部渲染为已提交。</p>
<p><b>修复</b>：1) inspectionRowToRecord 按 bizState 映射状态——0=待提交(draft)，1/2=已提交(submitted)，缺失时回落为已提交；详情页 getRecordAsync 共用该映射；2) fetchHistoryRemote / countHistory 按当前 tab 透传 bizStates 参数给后端做服务端筛选（待提交=bizStates 0，已提交归档=bizStates 1,2，all 不传），不再前端拉全量再过滤；3) 后端（liqiang，本 bug 重开时已派）需为 /inspection/page 新增 bizStates 逗号多选过滤参数，并确保提交后的记录能进入历史列表（对应原始 title 提交后历史记录没有这笔数据）。</p>
<p><b>验证</b>：新增 tests/flood-remote.test.ts，覆盖 bizState 到 status 映射与 bizStates 参数透传；vitest 全量 21 用例通过；提交 26c2892 已推送 origin/dev。构建未执行（仅单测）。请测试按 bizState 0/1/2 回归待提交与已提交归档 tab 切换、计数，以及提交后历史可见性。</p>',NULL,'fixed',0,0,'rnd');
